{
  "rules": [
    {
      "id": "P1-L1",
      "quote": "Implement `parse_amount(s)` to convert string amounts to cents."
    },
    {
      "id": "P1-L2",
      "quote": "- Input is a string with ordinary decimal notation, having at most two fractional digits."
    },
    {
      "id": "P1-L3",
      "quote": "- Convert positive amounts like \"12.30\" to 1230 and \"3\" to 300, and negative amounts like \"-2.00\" to -200."
    },
    {
      "id": "P1-L4",
      "quote": "- Return `None` for malformed or non-string input without raising or printing errors."
    },
    {
      "id": "P1-L5",
      "quote": "- Ensure every amount is calculated and stored as an integer number of cents."
    },
    {
      "id": "P2-L1",
      "quote": "Implement `parse_record(line)` to parse strings with order/payment info."
    },
    {
      "id": "P2-L2",
      "quote": "- Every line has five `|`-separated fields: `TYPE|RECORD_ID|ORDER_ID|AMOUNT|TIMESTAMP`."
    },
    {
      "id": "P2-L3",
      "quote": "- `TYPE` must be `ORDER` or `PAYMENT`, matched case-insensitively and stored uppercase."
    },
    {
      "id": "P2-L4",
      "quote": "- Trim `RECORD_ID` and `ORDER_ID`;"
    },
    {
      "id": "P2-L5",
      "quote": "reject the row if either becomes empty."
    },
    {
      "id": "P2-L6",
      "quote": "- For `ORDER`, `RECORD_ID` and `ORDER_ID` must be equal."
    },
    {
      "id": "P2-L7",
      "quote": "- Call `parse_amount` to handle `AMOUNT`;"
    },
    {
      "id": "P2-L8",
      "quote": "a negative `ORDER` is invalid, a negative `PAYMENT` is allowed as a refund."
    },
    {
      "id": "P2-L9",
      "quote": "- Parse `TIMESTAMP` in `YYYY-MM-DD HH:MM` format and store it as a naive `datetime`."
    },
    {
      "id": "P2-L10",
      "quote": "- Return a dictionary with `type`, `record_id`, `order_id`, `amount`, `timestamp` keys, or return `None` for invalid rows."
    }
  ],
