"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount, timestamp = fields
    record_type = record_type.strip().upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or (record_type == 'ORDER' and record_id != order_id):
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None or (record_type == 'ORDER' and parsed_amount < 0):
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': parsed_amount,
        'TIMESTAMP': parsed_timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []
    for record in records:
        if record['TYPE'] == 'ORDER':
            order_id = record['ORDER_ID']
            order_timestamp = record['TIMESTAMP']
            order_amount = record['AMOUNT']
            matched_payment = None

            for payment in records:
                if (payment['TYPE'] == 'PAYMENT' and 
                    payment['AMOUNT'] >= 0 and 
                    payment['ORDER_ID'] == order_id and 
                    order_timestamp <= payment['TIMESTAMP'] <= order_timestamp + timedelta(hours=72)):
                    if matched_payment is None or payment['TIMESTAMP'] < matched_payment['TIMESTAMP']:
                        matched_payment = payment

            if matched_payment:
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': matched_payment['AMOUNT']
                })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })
    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0:
            total_refund += abs(record['AMOUNT'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

