"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3].strip()
    timestamp = fields[4].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None

    amount_cents = parse_amount(amount)
    if amount_cents is None or (record_type == 'ORDER' and amount_cents < 0):
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    if not record_id or not order_id:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount_cents,
        'TIMESTAMP': parsed_timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = order['TIMESTAMP']
        matching_payments = [
            payment for payment in payments
            if payment['ORDER_ID'] == order_id and 
            0 <= (payment['TIMESTAMP'] - order_timestamp).total_seconds() <= 72 * 3600
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: p['TIMESTAMP'])
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    return sum(abs(record['AMOUNT']) for record in records if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches) - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

