"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_str, timestamp_str = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    if record_type == 'ORDER' and record_id != order_id:
        return None

    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            order_id = record['order_id']
            if order_id in orders:
                order = orders[order_id]
                time_difference = (order['timestamp'] - record['timestamp']).total_seconds()
                if 0 <= time_difference <= 72 * 3600:
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['amount']
                    })
                else:
                    results.append({
                        'order_id': order_id,
                        'status': 'unmatched',
                        'amount': 0
                    })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })

    for order_id in orders:
        if order_id not in [result['order_id'] for result in results]:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

