"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3].strip()
    timestamp_str = fields[4].strip()

    if not all([record_type, record_id, order_id, amount, timestamp_str]):
        return None

    if record_type == 'ORDER':
        if record_id != order_id:
            return None
    elif record_type != 'PAYMENT':
        return None

    amount_parsed = parse_amount(amount)
    if amount_parsed is None or (record_type == 'ORDER' and amount_parsed < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_parsed,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']

    for order in orders:
        matched_payment = None
        order_timestamp = order['timestamp']
        order_id = order['order_id']

        for payment in payments:
            if payment['order_id'] == order_id:
                time_difference = payment['timestamp'] - order_timestamp
                if timedelta(0) <= time_difference <= timedelta(hours=72):
                    if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'MATCHED',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'UNMATCHED',
                'amount': 0
            })

    return results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].upper() == 'MATCHED')
    net_total = sum(match['amount'] for match in matches if match['status'].upper() == 'MATCHED') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].upper() == 'UNMATCHED')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

