"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -2 or amount.as_tuple().exponent > 0:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount, timestamp = map(str.strip, fields)

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id:
        return None

    if record_type.upper() == 'ORDER' and record_id != order_id:
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None or (record_type.upper() == 'ORDER' and parsed_amount < 0):
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'timestamp': parsed_timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

