"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -2:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3].strip()
    timestamp = fields[4].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if record_type == 'ORDER' and (record_id == '' or order_id == '' or record_id != order_id):
        return None

    parsed_amount = parse_amount(amount)
    if record_type == 'ORDER' and (parsed_amount is None or parsed_amount < 0):
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'timestamp': parsed_timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record:
            records.append(record)

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] > 0]
    results = []

    for order in orders:
        matched_amount = 0
        order_timestamp = order['timestamp']
        order_id = order['order_id']

        for payment in payments:
            if payment['order_id'] == order_id and payment['timestamp'] <= order_timestamp + timedelta(hours=72):
                matched_amount += payment['amount']
                break  # Only match the earliest payment

        status = 'matched' if matched_amount > 0 else 'unmatched'
        results.append({'order_id': order_id, 'status': status, 'amount': matched_amount})

    return results


def compute_refunds(records):
    total_refund = sum(abs(record['amount']) for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

