"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -2:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3].strip()
    timestamp = fields[4].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if record_type == 'ORDER' and (record_id == '' or order_id == '' or record_id != order_id):
        return None
    amount_cents = parse_amount(amount)
    if record_type == 'ORDER' and amount_cents is not None and amount_cents < 0:
        return None
    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'timestamp': timestamp_dt
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']

    for order in orders:
        matched_amount = 0
        order_timestamp = order['timestamp']
        for payment in payments:
            if payment['order_id'] == order['order_id'] and payment['amount'] > 0:
                if order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72):
                    matched_amount += payment['amount']
                    payments.remove(payment)  # Remove matched payment
                    break  # Only match the earliest payment

        status = 'matched' if matched_amount > 0 else 'unmatched'
        results.append({
            'order_id': order['order_id'],
            'status': status,
            'amount': matched_amount
        })

    return results


def compute_refunds(records):
    total_refunds = sum(abs(record['amount']) for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return total_refunds


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

