    },
    {
      "id": "P2-L1",
      "quote": "Implement `parse_record(line)` to parse line into a dictionary."
    },
    {
      "id": "P2-L2",
      "quote": "- Each line contains exactly five `|`-separated fields: `TYPE|RECORD_ID|ORDER_ID|AMOUNT|TIMESTAMP`."
    },
    {
      "id": "P2-L3",
      "quote": "- `TYPE` should be `ORDER` or `PAYMENT`, store them uppercase."
    },
    {
      "id": "P2-L4",
      "quote": "Return `None` if it is neither."
    },
    {
      "id": "P2-L5",
      "quote": "- Trim and reject the row if any of `RECORD_ID` or `ORDER_ID` becomes empty."
    },
    {
      "id": "P2-L6",
      "quote": "- If `TYPE` is `ORDER`, ensure `RECORD_ID` equals `ORDER_ID`."
    },
    {
      "id": "P2-L7",
      "quote": "- Use `parse_amount` to process `AMOUNT`, reject negative amounts for `ORDER`."
    },
    {
      "id": "P2-L8",
      "quote": "- Parse the `TIMESTAMP` as a naive `datetime` in `YYYY-MM-DD HH:MM` format."
    },
    {
      "id": "P2-L9",
      "quote": "- Return a dictionary with keys: `type`, `record_id`, `order_id`, `amount`, and `timestamp` or `None` for invalid rows."
    }
  ],
