stageRows.noteAfterStage:
{
  "rules": [
    {
      "id": "P1-L1",
      "quote": "Implement the `parse_amount(s)` function."
    },
    {
      "id": "P1-L2",
      "quote": "- Convert a string representing a monetary amount to an integer number of cents."
    },
    {
      "id": "P1-L3",
      "quote": "- Input format: a string in ordinary decimal notation with at most two decimal places."
    },
    {
      "id": "P1-L4",
      "quote": "- Conversion examples: \"12.30\" becomes 1230, \"3\" becomes 300, \"-2.00\" becomes -200."
    },
    {
      "id": "P1-L5",
      "quote": "- Return `None` for **malformed** strings or non-string inputs."
    },
    {
      "id": "P2-L1",
      "quote": "Implement the `parse_record(line)` function."
    },
    {
      "id": "P2-L2",
      "quote": "- Input is a `line` with exactly five `|`-separated fields: `TYPE|RECORD_ID|ORDER_ID|AMOUNT|TIMESTAMP`."
    },
    {
      "id": "P2-L3",
      "quote": "- `TYPE` must be `ORDER` or `PAYMENT`, case-insensitive and stored as uppercase."
    },
    {
      "id": "P2-L4",
      "quote": "- The `RECORD_ID` and `ORDER_ID` must be equal for `ORDER` type."
    },
    {
      "id": "P2-L5",
      "quote": "- Use `parse_amount` to parse `AMOUNT`;"
    },
    {
      "id": "P2-L6",
      "quote": "reject negative order amounts."
    },
    {
      "id": "P2-L7",
      "quote": "- A negative `PAYMENT` `AMOUNT` is treated as a refund."
    },
    {
      "id": "P2-L8",
      "quote": "- `TIMESTAMP` should be parsed to a naive `datetime` format of `YYYY-MM-DD HH:MM`."
    },
    {
      "id": "P2-L9",
      "quote": "- Return a dictionary with keys `type`, `record_id`, `order_id`, `amount`, and `timestamp`."
    },
    {
      "id": "P2-L10",
      "quote": "- Return `None` for any invalid row, silently skipping it."
    }
  ],
  "checks": [],
  "status": {},
  "todo": []
}

